import {calculate,defaults,appliances} from './engine.js';
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',sun:'M12 3v1m0 16v1M3 12h1m16 0h1M5.6 5.6l.7.7m11.4 11.4.7.7m0-12.8-.7.7M6.3 17.7l-.7.7M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',battery:'M3 7h16v10H3zM21 10v4M7 10v4m4-4v4m4-4v4',grid:'M12 3 5 21m7-18 7 18M8 7h8M6 12h12M4 17h16M9 3h6',bolt:'m13 2-9 12h7l-1 8 10-13h-8z',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM8 12l3 3 5-6',leaf:'M20 3C8 2 3 7 4 14s12 10 16-11ZM4 20 15 9',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',chart:'M4 3v18h17M8 15l4-6 4 3 5-8',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',calendar:'M5 5h14v16H5zM8 3v4m8-4v4M5 10h14',wind:'M3 8h12a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h5a3 3 0 1 1-3 3',coin:'M16 8c-4-4-9 0-9 4s5 8 9 4M4 10h9M4 14h9',pause:'M8 5v14m8-14v14',play:'m7 4 13 8-13 8z',washer:'M4 3h16v18H4zM4 8h16M7 5.5h1M16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'m5 12 4 4 10-10',people:'M15 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M5 21v-3a7 7 0 0 1 14 0v3M18 5a3 3 0 0 1 0 6M21 20v-3',plug:'M8 3v5m8-5v5M6 8h12v4a6 6 0 0 1-12 0zM12 18v4'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.bolt}"/></svg>`;
let state={...defaults,devices:[...defaults.devices]},tab='home',selectedHour=18,receipt=null;
let plan=calculate(state);
const modes={saving:{name:'省钱优先',icon:'coin',desc:'在满足最低保障的前提下，更多利用低价电与太阳能。'},balanced:{name:'智能平衡',icon:'leaf',desc:'在电费、日常用电与备电之间，找到适合你家的平衡。'},backup:{name:'安心备电',icon:'shield',desc:'优先为关键设备留足电，减少非必要的电池放电。'}};
const money=n=>`${n<0?'−':''}€${Math.abs(n).toFixed(2)}`;
const time=n=>`${String(n).padStart(2,'0')}:00`;
const target=document.getElementById('app');
const deviceNames=()=>state.devices.map(id=>appliances[id].name).join('、')||'尚未选择的关键设备';
const stormReserveText=()=>calculate({...state,storm:false}).reserve<plan.reserve?'提高至':'维持在';
function header(){return `<header><div class="brand"><span class="brand-icon">${icon('home')}</span><strong>HEIM<span style="color:#7fa65b">.</span></strong><small>家庭能源管家</small></div><nav aria-label="主要导航">${[['home','home','我的家'],['plan','chart','24 小时计划'],['settings','sliders','家庭设置']].map(([id,i,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="account"><div class="account-copy">林家的能源空间<small>慕尼黑 · 德国</small></div><span class="avatar" aria-label="林家">L</span></div></header>`;}
function heading(title,sub,eyebrow){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div><div class="top-meta"><span class="date">${icon('calendar')}9 月 25 日 · 星期五</span><span class="pill demo">交互演示</span></div></div>`;}
function banner(){return `${state.paused?`<div class="banner">${icon('pause')}自动调度已暂停。以下为计划预览，模拟动作不会执行；恢复后将按最新偏好继续。<button class="text-button" data-action="pause">恢复</button></div>`:''}${state.storm?`<div class="banner">${icon('wind')}强风场景已开启 · 备电目标${stormReserveText()} ${plan.reserve}%，光伏预测下调。天气风险不代表一定停电。</div>`:''}`;}
function chart(){const max=.5,w=650,h=170,x=i=>42+i*25.2,y=v=>h-v/max*145;return `<div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 650 206" role="img" aria-label="24 小时模拟电价和光伏预测，最低电价凌晨三点，每千瓦时 0.14 欧元">${[.1,.2,.3,.4,.5].map(v=>`<line class="chart-grid" x1="40" x2="641" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="0" y="${y(v)+4}">${v.toFixed(2)}</text>`).join('')}${plan.hours.map((v,i)=>`<rect x="${x(i)-6}" y="${170-v.pv*40}" width="12" height="${v.pv*40}" rx="3" fill="#d7e7b8"/>`).join('')}<path d="M ${plan.hours.map((v,i)=>`${x(i)},${y(v.price)}`).join(' L ')} L 622,170 L 42,170 Z" fill="#bfd8b0" opacity=".12"/><path class="chart-line" d="M ${plan.hours.map((v,i)=>`${x(i)},${y(v.price)}`).join(' L ')}"/><circle cx="${x(3)}" cy="${y(.14)}" r="4" fill="#567c45" stroke="white" stroke-width="2"/>${[0,3,6,9,12,15,18,21,23].map(i=>`<text class="chart-label" x="${x(i)}" y="196" text-anchor="middle">${String(i).padStart(2,'0')}:00</text>`).join('')}</svg></div>`;}
function flow(){const current=plan.hours[14],battery=current.charge>.005?`+${current.charge.toFixed(2)}`:current.discharge>.005?`−${current.discharge.toFixed(2)}`:'0.00';const routes=[current.pv>.005?'M135 70H230Q250 70 250 100V130':null,current.grid>.005?'M465 70H370Q350 70 350 100V130':current.export>.005?'M350 130V100Q350 70 370 70H465':null,current.charge>.005?'M250 130V175Q250 205 230 205H135':current.discharge>.005?'M135 205H230Q250 205 250 175V130':null,'M350 130V175Q350 205 370 205H465'].filter(Boolean);return `<section class="card flow-card"><div class="card-title"><h2>家的能量，正在流动</h2><span class="live ${state.paused?'pause-badge':''}">${state.paused?'调度已暂停':'明日 14:00 · 模拟回放'}</span></div><div class="flow-diagram"><svg class="flow-lines ${state.paused?'paused':''}" viewBox="0 0 600 260" preserveAspectRatio="none" aria-hidden="true"><path d="M135 70H230Q250 70 250 100V130M465 70H370Q350 70 350 100V130M135 205H230Q250 205 250 175V130M465 205H370Q350 205 350 175V130"/>${routes.map(d=>`<path class="moving" d="${d}"/>`).join('')}</svg><div class="energy-node solar">${icon('sun')}<span>太阳能发电</span><strong>${current.pv.toFixed(2)} <small>kW</small></strong></div><div class="energy-node grid">${icon('grid')}<span>${current.export>.001?'余电上网':'电网购电'}</span><strong>${(current.export>.001?current.export:current.grid).toFixed(2)} <small>kW</small></strong></div><div class="energy-center">${icon('home')}<strong>林家的能源空间</strong><small>${state.paused?'自动调度暂停':current.action}</small></div><div class="energy-node battery">${icon('battery')}<span>家庭储能 · ${current.soc.toFixed(0)}%</span><strong>${battery} <small>kW</small></strong></div><div class="energy-node home">${icon('plug')}<span>家庭用电</span><strong>${current.load.toFixed(2)} <small>kW</small></strong></div></div><div class="flow-footer"><span>${icon('shield')}备电底线 ${plan.reserve}% · ${state.storm?'风险储备已增加':state.devices.length?'按所选设备预留':'请先选择关键设备'}</span><button class="text-button" data-action="pause">${icon(state.paused?'play':'pause')}${state.paused?'恢复调度':'暂停调度'}</button></div></section>`;}
function metrics(){return `<div class="metrics">${[
 ['预计节省','coin',money(plan.savings),'',`相比固定自用策略${plan.savings>=0?'减少':'增加'}电费 <b>${money(Math.abs(plan.savings))}</b>`],
 ['太阳能自用率','sun',plan.selfUse.toFixed(0),'%',`明日预计发电 <b>${plan.solar.toFixed(1)} kWh</b>`],
 ['目标备电时长','shield',plan.backupHours.toFixed(1),'小时',`${state.devices.length} 类关键设备 · 储备达到 ${plan.reserve}% 时`],
 ['今日用电偏好','leaf',modes[state.mode].name,'',state.paused?'已暂停 · 仅展示计划':'管家将按这个目标安排能源']
 ].map(([name,i,value,unit,foot],n)=>`<section class="card metric"><div class="metric-top">${name}${icon(i)}</div><div class="metric-value" ${n===3?'style="font-size:25px;padding-top:5px"':''}>${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></section>`).join('')}</div>`;}
function modeControls(){return `<div class="mode-options" role="group" aria-label="用电目标">${Object.entries(modes).map(([id,m])=>`<button class="${state.mode===id?'selected':''}" data-mode="${id}" aria-pressed="${state.mode===id}">${icon(m.icon)}${m.name}</button>`).join('')}</div><p class="mode-description">${modes[state.mode].desc}</p><div class="weather-row"><div class="weather-label">${icon('wind')}<div><strong>模拟明日强风</strong><small>体验管家如何提前增加备电</small></div></div><button role="switch" aria-label="模拟明日强风" aria-checked="${state.storm}" class="switch" data-action="storm"></button></div>`;}
function home(){return `${heading('下午好，林家的能量已安排好。','让太阳能多做一点，让你少操心一点。','YOUR HOME, IN BALANCE')}${banner()}<div class="dashboard">${flow()}<section class="card recommend"><div class="card-title"><span class="ai-icon">${icon('spark')}</span><span class="pill green">${state.storm?'备电建议已更新':'你的专属能源建议'}</span></div><h3>${state.storm?'风雨来之前，<br><em>先为家留一份安心。</em>':state.mode==='backup'?'把电留给，<br><em>家里最重要的日常。</em>':'把便宜的电，<br><em>留给热闹的晚餐。</em>'}</h3><p>${state.storm?`明日光伏发电预计减少，管家已将备电目标${stormReserveText()} ${plan.reserve}%。达到目标后，可为关键设备提供约 ${plan.backupHours.toFixed(1)} 小时用电。`:state.mode==='backup'?`将至少保留 ${plan.reserve}% 电量，优先保障你选择的${deviceNames()}。只有超出储备的电量才参与高价时段供电。`:`你家通常在 ${state.dinner}:00 开始用电高峰。管家将提前储能，在晚间高价时段优先使用电池，同时为太阳能留出空间。`}</p><button class="button full" data-tab="plan">查看我的 24 小时计划 ${icon('arrow')}</button></section>${metrics()}</div><div class="bottom-grid"><section class="card"><div class="card-title"><h2>明日能源趋势</h2><div class="chart-legend"><span><i class="line"></i>电价</span><span><i></i>光伏预测</span></div></div><span class="chart-axis-label">电价 €/kWh · 光伏柱高为相对趋势</span>${chart()}<div class="chart-note">${icon('spark')}03:00 电价最低 €0.14/kWh · ${state.dinner}:00 晚餐前提前做好准备</div></section><section class="card"><div class="card-title"><h2>按你的节奏用电</h2><span class="small">随时可调整</span></div>${modeControls()}</section></div>`;}
function hourDetail(){const h=plan.hours[selectedHour];return `<div class="detail-panel" aria-live="polite"><h3>${time(h.hour)}–${time(h.hour+1)} · ${h.action}</h3><p>${h.reason}${plan.laundryStart!==null&&(h.hour===plan.laundryStart||h.hour===plan.laundryStart+1)?' 洗衣任务也安排在这个低价窗口。':''}</p><div class="detail-stats"><span>电价<b>€${h.price.toFixed(2)}</b></span><span>时段末电量<b>${h.soc.toFixed(0)}%</b></span><span>家庭用电<b>${h.load.toFixed(2)} kWh</b></span></div></div>`;}
function planPage(){return `${heading('明天的每一度电，都有安排。','点选一个时段，看看管家为什么这样做。','A PLAN THAT KNOWS YOU')}${banner()}<div class="plan-layout"><div><section class="card"><div class="card-title"><h2>24 小时能源计划</h2><span class="pill green">${modes[state.mode].name}</span></div><div class="chart-legend"><span><i class="line"></i>电价 €/kWh</span><span><i></i>光伏预测（相对趋势）</span></div>${chart()}<div class="timeline" role="group" aria-label="逐小时能源安排">${plan.hours.map(h=>`<button class="hour-block ${h.color} ${selectedHour===h.hour?'selected':''}" data-hour="${h.hour}" aria-pressed="${selectedHour===h.hour}" aria-label="${time(h.hour)} ${h.action}"><b>${String(h.hour).padStart(2,'0')}:00</b>${icon(h.color==='solar'?'sun':h.color==='charge'?'bolt':h.color==='discharge'?'battery':'shield')}<small>${h.action}</small></button>`).join('')}</div>${hourDetail()}</section><section class="card" style="margin-top:20px"><div class="card-title"><h2>生活照常，能源跟上</h2><button class="text-button" data-tab="settings">调整家庭作息 ${icon('chevron')}</button></div><div class="schedule-task">${icon('home')}<div><strong>${state.dinner}:00–${state.dinner+2}:00 · 一家人的晚餐时光</strong><p>根据家庭作息输入，预留晚餐高峰用电。演示画像，尚未进行真实习惯学习。</p></div></div><div class="schedule-task">${icon('washer')}<div><strong>${state.laundry?`${time(plan.laundryStart)}–${time(plan.laundryStart+2)} · 洗衣已排入低价时段`:'洗衣任务 · 交给便宜的时段'}</strong><p>${state.laundry?`在明日 ${time(state.deadline)} 前完成，预计用电 1 kWh，按时段电价估算约 ${money(plan.laundryCost)}。`:'设定完成时间，管家会在明日凌晨挑选连续 2 小时的低价窗口。'}</p></div></div><div class="inline-actions"><label class="sub" for="deadline">明早完成时间</label><select id="deadline" aria-label="洗衣完成时间">${[6,7,8,9].map(h=>`<option value="${h}" ${state.deadline===h?'selected':''}>${time(h)} 前</option>`).join('')}</select><button class="button ${state.laundry?'outline':'light'}" data-action="laundry">${state.laundry?'取消洗衣任务':'安排洗衣任务'}</button></div></section></div><aside class="plan-side"><section class="card"><div class="card-title"><h2>这份计划，带来什么？</h2>${icon('leaf')}</div><div class="metric-value">${money(plan.savings)}</div><p class="sub">${plan.savings>=0?'预计节省':'保障优先，预计多支出'} · 相比固定自用策略</p><div class="cost-row"><span>固定自用策略</span><b>${money(plan.baseline)}</b></div><div class="cost-bar"><i style="width:${Math.max(5,plan.baseline/Math.max(plan.baseline,plan.cost,.01)*100)}%"></i></div><div class="cost-row"><span>能源管家计划</span><b>${money(plan.cost)}</b></div><div class="cost-bar green"><i style="width:${Math.max(5,plan.cost/Math.max(plan.baseline,plan.cost,.01)*100)}%"></i></div><p class="sub" style="margin-top:19px;font-size:12px">同一用电与光伏输入；包含充放电损耗，电费对比未计电池折旧。模拟价格含税，售电 €0.08/kWh。</p><button class="text-button" style="margin-top:12px" data-action="method">查看计算口径 ${icon('chevron')}</button></section><section class="card"><div class="card-title"><h2>把计划交给管家</h2>${icon('shield')}</div><p class="sub">${state.paused?'自动调度已暂停，恢复后才能模拟应用计划。':`备电目标 ${plan.reserve}%，已检查电池电量与充放电上限。你可以模拟应用本次计划。`}</p><button class="button full" style="margin-top:20px" data-action="execute" ${state.paused?'disabled':''}>${icon('check')}模拟应用计划</button>${receipt?`<div class="receipt">${icon('check')}模拟回执 · ${receipt.time}<br>备电目标 ${receipt.reserve}% · ${receipt.mode}<br>24 个时段已应用到演示状态，未向真实设备发送指令。</div>`:'<p class="sub" style="font-size:11px;margin-top:12px">仅模拟执行，不连接或控制真实设备。</p>'}</section><section class="card">${modeControls()}</section></aside></div>`;}
function settings(){return `${heading('一个懂你家的管家。','告诉我们你的日常，其余的交给能源计划。','BUILT AROUND YOUR LIFE')}${banner()}<div class="settings-layout"><section class="card profile-card"><div class="family-symbol">${icon('people')}</div><div><h2>林家 · 德国三口之家</h2><p>工作日白天外出，晚间一家人一起做饭。<br>希望自动省钱，也为重要的日常留好电。</p></div><div class="profile-tags"><span>动态电价</span><span>屋顶光伏</span><span>家庭储能</span></div></section><section class="card"><div class="card-title"><h2>家的生活节奏</h2>${icon('clock')}</div><div class="field"><label class="field-label" for="dinner">晚餐用电高峰 <output id="dinner-label">${time(state.dinner)}–${time(state.dinner+2)}</output></label><input id="dinner" type="range" min="17" max="20" step="1" value="${state.dinner}" aria-label="晚餐开始时间"><p class="sub">高峰持续约 2 小时；管家会提前保留可用电量。</p></div><div class="field"><div class="field-label">你希望管家优先考虑什么？</div>${modeControls()}</div></section><section class="card"><div class="card-title"><h2>停电时，哪些设备不能停？</h2>${icon('shield')}</div>${Object.entries(appliances).map(([id,a])=>`<label class="device-row"><input type="checkbox" data-device="${id}" ${state.devices.includes(id)?'checked':''}><span>${a.name}</span><small>${Math.round(a.power*1000)} W</small></label>`).join('')}<div class="field" style="border-top:0"><label class="field-label" for="backup-hours">最低保障时长 <select id="backup-hours">${[2,4,8,12].map(h=>`<option value="${h}" ${state.backupHours===h?'selected':''}>${h} 小时</option>`).join('')}</select></label><p class="sub">关键设备按持续平均功率估算，实际运行时间会随用电变化。</p></div></section><section class="card setting-summary"><div class="card-title"><h2>动态备电目标</h2><span class="pill green">随设置即时更新</span></div><div class="big-reserve">${plan.reserve}<small>% 电池电量</small></div><div class="reserve-track"><i style="width:${plan.reserve}%"></i></div><p class="sub">${state.devices.length?`保障 ${Math.round(plan.essential*1000)} W 关键负载，储备达到目标后预计支持 ${plan.backupHours.toFixed(1)} 小时。`:'尚未选择关键设备。选择设备后可估算保障时长。'}</p>${plan.insufficient?'<p class="notice">当前容量不足以满足所选保障时长，目标已设为 95%。请减少关键设备或降低保障时长。</p>':''}<p class="sub" style="margin-top:12px;font-size:12px">综合用电偏好、最低保障与天气风险确定目标。${state.storm?'强风场景要求至少保留 65%。':'天气风险正常。'}</p></section><section class="card"><div class="card-title"><h2>家庭能源设备</h2><span class="small">模拟配置</span></div><div class="equipment"><span>家庭电池 <small>10 kWh</small></span><span class="pill green">模拟在线</span></div><div class="equipment"><span>屋顶光伏 <small>4 kWp</small></span><span class="pill green">模拟在线</span></div><div class="equipment"><span>智能电表 + 洗衣插座</span><span class="pill green">模拟在线</span></div><p class="sub" style="font-size:12px;margin-top:12px">电池充放电上限 2.5 kW；充电效率 95%，放电效率 90%。支持备电的接线与硬件能力为演示假设。</p></section><div class="settings-note">设置在当前演示会话中立即生效，刷新后恢复默认。此 Demo 不采集真实家庭数据，不连接 Anker 或 EcoFlow 设备。</div></div>`;}
function render(){const focused=document.activeElement;const focusKey=focused&&['id','data-tab','data-mode','data-action','data-hour','data-device'].find(a=>focused.hasAttribute(a));const focusValue=focusKey?focused.getAttribute(focusKey):null;plan=calculate(state);target.innerHTML=`${header()}<main>${tab==='home'?home():tab==='plan'?planPage():settings()}<footer><span>HEIM · 让能源适应生活</span><span>模拟数据 · 德国家庭场景 · 2026.09.25 <button class="text-button" style="display:inline;font-size:11px;margin-left:12px" data-action="about">关于此演示</button></span></footer></main>`;if(focusKey&&focusValue)target.querySelector(`[${focusKey}="${focusValue}"]`)?.focus({preventScroll:true});}
let toastTimer;
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function change(patch,message){state={...state,...patch};receipt=null;render();if(message)toast(message);}
function modal(type){const body=type==='about'?`<p class="eyebrow">ABOUT HEIM</p><h2>家庭能源管家 · 产品演示</h2><p>根据《欧洲家庭能源管家产品提案》制作，面向德国拥有光伏、储能与动态电价的家庭。</p><p>参考 Anker SOLIX 的能源监测和 EcoFlow 的家庭能源管理体验；本产品与两者无隶属关系。</p><p><a href="https://www.anker.com/de/products/a17c5" target="_blank" rel="noopener">Anker SOLIX 产品参考 ↗</a><br><a href="https://energy.ecoflow.com/uk/hems/ecoflow-app" target="_blank" rel="noopener">EcoFlow HEMS 产品参考 ↗</a></p><p class="notice">电价、天气、设备与收益均为模拟。没有真实设备控制，也没有接入电价或天气 API。</p>`:`<p class="eyebrow">CLEAR BY DESIGN</p><h2>每一个数字，都说清楚。</h2><div class="explainer-row">${icon('coin')}<div><h4>预计节省怎么算？</h4><p>固定策略与管家使用相同负载、光伏和初始电量 68%。固定策略优先太阳能供电，有剩余就存电，缺电时用电池至 30%；管家额外考虑价格和动态备电。两者电网购电费用减售电收入之差就是预计节省。计划采用整日模拟预测计算，并以每度放电 0.005–0.025 欧元的损耗偏好惩罚减少不必要循环。管家在日末保留的电量不低于固定策略，避免通过额外耗尽电池夸大节省；较多的日末储备未折价。</p></div></div><div class="explainer-row">${icon('shield')}<div><h4>备电时长怎么算？</h4><p>目标储能 × 放电效率 ÷ 关键设备总功率。它表示达到目标后的估算时长，不代表此刻已经充足。若目标超过当前电量，将先补能。</p></div></div><div class="explainer-row">${icon('sun')}<div><h4>太阳能自用率怎么算？</h4><p>当日未外送的太阳能占总发电量比例，包含储存在电池中的电量。此处未扣除储能转换损耗。</p></div></div><p class="notice">演示电价按含税口径，售电 €0.08/kWh。未计算电池折旧或固定电费，不是实际节省承诺。</p>`;document.getElementById('detail-content').innerHTML=body;document.getElementById('detail').showModal();}
target.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();const heading=target.querySelector('h1');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.mode){change({mode:b.dataset.mode},`已切换为${modes[b.dataset.mode].name}，计划已更新`);return;}if(b.dataset.hour!==undefined){selectedHour=Number(b.dataset.hour);render();target.querySelector(`[data-hour="${selectedHour}"]`)?.focus({preventScroll:true});return;}switch(b.dataset.action){case 'storm':change({storm:!state.storm},state.storm?'已恢复正常天气，计划已重算':'已增加天气风险储备，计划已重算');break;case 'pause':state.paused=!state.paused;render();toast(state.paused?'自动调度已暂停，你可以继续调整计划':'已恢复自动调度');break;case 'laundry':change({laundry:!state.laundry},state.laundry?'已取消洗衣任务':'已选择最低价的连续两小时安排洗衣');break;case 'execute':if(state.paused)return;receipt={reserve:plan.reserve,mode:modes[state.mode].name,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})};render();toast('模拟计划已应用，可查看执行回执');break;case 'method':modal('method');break;case 'about':modal('about');break;}});
target.addEventListener('input',e=>{if(e.target.id==='dinner'){document.getElementById('dinner-label').textContent=`${time(+e.target.value)}–${time(+e.target.value+2)}`;}});
target.addEventListener('change',e=>{const el=e.target;if(el.id==='dinner'){change({dinner:+el.value},'晚餐高峰已更新，管家会提前准备电量');target.querySelector('#dinner')?.focus({preventScroll:true});}if(el.id==='backup-hours'){change({backupHours:+el.value},'最低保障时长已更新');target.querySelector('#backup-hours')?.focus({preventScroll:true});}if(el.id==='deadline')change({deadline:+el.value},state.laundry?'洗衣任务已重新安排':null);if(el.dataset.device){change({devices:el.checked?[...state.devices,el.dataset.device]:state.devices.filter(id=>id!==el.dataset.device)},'关键设备和备电目标已更新');target.querySelector(`[data-device="${el.dataset.device}"]`)?.focus({preventScroll:true});}});
const dialog=document.getElementById('detail');dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_energy_preference',description:'Change the simulated household energy preference and recompute the visible plan.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['saving','balanced','backup']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Object.hasOwn(modes,input.mode)||Object.keys(input).some(k=>k!=='mode'))throw new Error('Invalid energy preference');change({mode:input.mode});return {mode:state.mode,reserve:plan.reserve,estimatedSavings:plan.savings};}})).catch(()=>{});}catch{}}
